// A function with a specific signature
void someFunc(int, double);

// Template with a by-value parameter
template<typename T>
void f1(T param); // param passed by value

// Template with a by-reference parameter
template<typename T>
void f2(T& param); // param passed by reference

// Deduction examples
f1(someFunc);  // T is deduced as void (*)(int, double)
               // param is a function pointer

f2(someFunc);  // T is deduced as void(int, double)
               // param is a function reference: void (&)(int, double)
